def _push_notification(account_id: str, text: str):
    """Атомарно кладёт уведомление BORIS в общий notification store."""
    from app.db.session import SessionLocal as _SL
    from app.services.notification_store import append_notification
    from datetime import datetime as _dt_notif
    db=_SL()
    try:
        append_notification(db,account_id,{"ts":_dt_notif.now().isoformat(timespec="seconds"),"text":text,"related_results":[],"read":False},commit=True)
    except Exception:
        db.rollback()
    finally:
        db.close()


def check_category_content_match(drafts: list) -> list:
    """Один батч-запрос в GPT: для каждого объявления партии сверяет title/description с
    назначенной category - явные несоответствия (например 'Производство кухонь' в категории
    'Шкафы и буфеты') возвращаются списком, остальное считается нормой. НЕ блокирует публикацию
    само по себе - это мягкая подсказка владельцу, в отличие от жёсткого xmlcheck ниже.
    Возвращает [] если несоответствий не найдено или проверка не удалась (не блокируем публикацию
    из-за недоступности ИИ - это не критическая проверка формата)."""
    from gigachat_pool import chat_with_fallback
    from gigachat.models import Messages, MessagesRole
    import json as _json_cm
    import re as _re_cm

    if not drafts:
        return []

    lines = []
    for i, d in enumerate(drafts):
        desc_snippet = _re_cm.sub(r"<[^>]+>", " ", (d.get("description") or ""))[:200].strip()
        lines.append(f"{i}: категория=\"{d.get('category', '')}\" | заголовок=\"{d.get('title', '')}\" | описание=\"{desc_snippet}\"")

    prompt = (
        "Ниже список объявлений Avito с назначенной им категорией (индекс: категория | заголовок | описание).\n"
        "Проверь КАЖДОЕ: явно ли заголовок/описание НЕ соответствует назначенной категории "
        "(например категория 'Шкафы и буфеты', а речь о кухнях, или категория 'Услуги переезда', а "
        "текст про ремонт квартир). Не придирайся к мелочам и синонимам - только ЯВНЫЕ, однозначные "
        "несоответствия ниши товара/услуги категории.\n\n"
        + "\n".join(lines) +
        "\n\nВерни ТОЛЬКО чистый JSON-массив ТОЛЬКО спорных индексов (пустой массив, если всё в порядке):\n"
        '[{"index": 0, "reason": "коротко почему не подходит", "suggested_category": "предполагаемая правильная категория"}]'
    )

    try:
        raw = chat_with_fallback([Messages(role=MessagesRole.USER, content=prompt)], temperature=0.1, max_tokens=2000).strip()
        raw = raw.replace("```json", "").replace("```", "").strip()
        start = raw.find("[")
        end = raw.rfind("]")
        if start != -1 and end != -1:
            raw = raw[start:end + 1]
        mismatches = _json_cm.loads(raw)
        if not isinstance(mismatches, list):
            return []
    except Exception as e:
        print(f"[check_category_content_match] проверка не удалась (пропускаем, не блокируем публикацию): {e}", flush=True)
        return []

    result = []
    for m in mismatches:
        idx = m.get("index")
        if not isinstance(idx, int) or idx < 0 or idx >= len(drafts):
            continue
        d = drafts[idx]
        result.append({
            "id": d.get("id"),
            "title": d.get("title", ""),
            "category": d.get("category", ""),
            "reason": m.get("reason", ""),
            "suggested_category": m.get("suggested_category", ""),
        })
    return result


def _publish_drafts_impl(req: PublishDraftsRequest, db):
    drafts = _load_drafts(req.account_id)
    to_publish = [d for d in drafts if not req.draft_ids or d.get("id") in req.draft_ids]
    remaining = [d for d in drafts if req.draft_ids and d.get("id") not in req.draft_ids]

    if not to_publish:
        return {"status": "ok", "published": 0}

    # ПРАВИЛО 3 КОНСТИТУЦИИ: массовая операция свыше 10 объектов идёт только
    # с подтверждения, и человек обязан видеть последствия. Порог считается по
    # числу НОВЫХ публикаций в этой партии, а не по размеру аккаунта: 150 старых
    # плюс 3 новых подтверждения не требуют, 40 новых — требуют.
    MASS_PUBLISH_LIMIT = 10
    if not req.confirmed and len(to_publish) > MASS_PUBLISH_LIMIT:
        _names = [d.get("title") or "без названия" for d in to_publish[:10]]
        _more = len(to_publish) - len(_names)
        return {
            "status": "needs_confirmation",
            "reason": "mass_publish",
            "count": len(to_publish),
            "message": ("Будет опубликовано %s объявлений. После публикации они станут "
                        "доступны покупателям на Avito. Автоматический откат невозможен — "
                        "снимать придётся вручную. Продолжить?" % len(to_publish)),
            "titles": _names,
            "more": ("...ещё %s" % _more) if _more > 0 else "",
        }

    # МЯГКАЯ ПРОВЕРКА СООТВЕТСТВИЯ КАТЕГОРИИ СОДЕРЖАНИЮ - до xmlcheck. Не критическая ошибка
    # формата (xmlcheck такое не ловит - категория технически валидна, просто не та по смыслу),
    # поэтому НЕ отменяет публикацию сама, а требует явного подтверждения владельца один раз
    # (инцидент: аккаунту Москва по аналогии с Пензой применили "Шкафы и буфеты", хотя там
    # "Производство кухонь" - категория была валидной строкой, но неверной по содержанию).
    if not req.confirmed:
        mismatches = check_category_content_match(to_publish)
        if mismatches:
            return {
                "status": "needs_confirmation",
                "message": f"Борис заметил возможное несоответствие категории содержанию у {len(mismatches)} из {len(to_publish)} объявлений - проверьте перед публикацией.",
                "mismatches": mismatches,
            }

    # ОБЯЗАТЕЛЬНАЯ ВАЛИДАЦИЯ ФИДА ПЕРЕД ПУБЛИКАЦИЕЙ: раньше ошибки формата (например,
    # отсутствующие обязательные ServiceType/ServiceSubtype) вылезали ПОСЛЕ того, как
    # объявления уже улетели на Avito - чинили постфактум вручную (инцидент "Книга жизни",
    # 22 черновика; аккаунт Георгия унаследовал чужие поля). Гоняем именно ЭТУ партию через
    # официальный валидатор Avito ДО того, как что-либо сохранится в фид - через
    # feed_preview, который ничего не публикует и не сохраняет.
    import asyncio as _asyncio_publish
    from app.api.parser import validate_feed_xmlcheck

    ids_param = ",".join(d.get("id") for d in to_publish if d.get("id"))
    preview_url = f"https://boris-ai.pro/api/avito/feed_preview/{req.account_id}.xml?ids={ids_param}"
    try:
        validation = _asyncio_publish.run(validate_feed_xmlcheck(preview_url))
    except Exception as e:
        validation = {"status": "error", "errors": [str(e)], "raw_text": ""}

    if validation.get("status") != "ok":
        titles = [d.get("title", "без названия") for d in to_publish]
        raw_lines = [l.strip() for l in (validation.get("raw_text") or "").split("\n") if l.strip()]
        noise = {"Отчёт о проверке", "Общий статус", "По ссылке", "Проверить", "XML-фид"}
        readable_errors = [l for l in raw_lines if l not in noise and len(l) > 3][:50]
        if validation.get("status") == "errors":
            message = f"Фид не прошёл проверку официального валидатора Avito - публикация {len(to_publish)} объявлений отменена."
        else:
            message = "Не удалось проверить фид валидатором Avito (валидатор недоступен или не ответил вовремя) - публикация отменена, чтобы не публиковать вслепую."
        _audit_log(req.account_id, "publish_validation_failed",
                   f"{message} Статус валидатора: {validation.get('status')}. Объявления: {', '.join(titles)[:300]}",
                   actor="boris")
        _push_notification(req.account_id, f"⚠️ {message}")
        return {
            "status": "validation_failed",
            "message": message,
            "validation_status": validation.get("status"),
            "items": titles,
            "errors": readable_errors or validation.get("errors") or ["Валидатор не вернул подробностей"],
        }

    _audit_log(req.account_id, "publish_validation_ok",
               f"Фид проверен валидатором Avito перед публикацией ({len(to_publish)} объявлений) - ошибок формата не найдено",
               actor="boris")

    existing_feed = _load_feed_items(req.account_id)
    # адреса публикации: draft_addresses (раздача по районам/городам) приоритетнее общего city
    _addr_map = getattr(req, "draft_addresses", {}) or {}
    _dbegin = getattr(req, "date_begin", "")
    for _d in to_publish:
        _aid = _d.get("id")
        if _aid in _addr_map and _addr_map[_aid]:
            _d["address"] = _addr_map[_aid]
        elif getattr(req, "city", ""):
            _d["address"] = req.city
        if _dbegin:
            _d["date_begin"] = _dbegin  # Avito отложит публикацию до этой даты
        if getattr(req, "timezone", ""):
            _d["timezone"] = req.timezone
    new_feed_items = [_draft_to_feed_item(d) for d in to_publish]

    # --- Контрактная проверка категории (врезка 1/3) ---
    # Проверяются ТОЛЬКО новые объявления. existing_feed уже сохранён и повторной
    # проверке не подлежит: у старых записей template_id пуст, и они не должны
    # блокировать публикацию новых. Атомарность: один невалидный новый элемент с
    # контрактом -> не сохраняется НИ ОДИН новый, старый фид остаётся прежним.
    _new_with = [it for it in new_feed_items if str(getattr(it, "template_id", "") or "").strip()]
    _new_without = [it for it in new_feed_items if not str(getattr(it, "template_id", "") or "").strip()]
    _contract_report = None
    if _new_with:
        from app.api.feed_contract import validate_feed_batch as _vfb
        _contract_report = _vfb(_new_with, {})
        if not _contract_report["ok"]:
            _titles = {it.id: it.title for it in new_feed_items}
            _audit_log(req.account_id, "publish_contract_failed",
                       f"Публикация отменена: {len(_contract_report['blocked'])} объявлений не прошли контракт категории",
                       actor="boris")
            return {
                "status": "error",
                "contract_status": "contract_failed",
                "message": "Часть объявлений не прошла проверку категории. Публикация отменена, черновики сохранены.",
                "checked": len(_new_with),
                "blocked": _contract_report["blocked"],
                "blocked_count": len(_contract_report["blocked"]),
                "by_code": _contract_report["by_code"],
                "without_contract": [it.id for it in _new_without],
                "contract_report": [
                    {"item_id": r["id"], "title": _titles.get(r["id"], ""),
                     "template_id": r["template_id"], "category_leaf": r["category_leaf"],
                     "code": e["code"], "field": e.get("field", ""),
                     "label": e.get("label", "") or e.get("field", ""),
                     "current_value": e.get("value", ""),
                     "allowed_values": e.get("allowed_values", []),
                     "format_rule": e.get("format_rule", ""),
                     "message": e.get("message", "")}
                    for r in _contract_report["items"] if not r["valid"] for e in r["errors"]
                ],
            }

    # FEED_PUBLISH_UPSERT_ATOMIC_V1: official validation may take long enough for
    # another worker to change the feed. Upsert only the just-published ids against
    # the latest locked snapshot instead of overwriting with stale existing_feed.
    _upsert_feed_items(req.account_id, new_feed_items)
    # DRAFT_PUBLISH_REMOVE_ATOMIC_V1: validation may take long enough for another
    # worker to append/edit drafts. Remove only the ids actually published from the
    # latest locked snapshot instead of overwriting with the stale pre-validation list.
    _published_ids = {str(d.get("id") or "") for d in to_publish if str(d.get("id") or "").strip()}
    _mutate_drafts(req.account_id, lambda rows: [d for d in rows if str(d.get("id") or "") not in _published_ids])
    # Журнал: одна сводная запись на всю партию (правило 0 Конституции).
    # Список id и названий нужен потому, что автоматического отката у публикации
    # нет — по нему клиент поймёт, что именно снимать вручную, если ошибся.
    try:
        from app.services.action_log import log_action, ACTOR_USER
        _pub = [(d.get("id") or "", d.get("title") or "без названия") for d in to_publish]
        _lines = ["%s — %s" % (i, t) for i, t in _pub[:40]]
        if len(_pub) > 40:
            _lines.append("...ещё %s" % (len(_pub) - 40))
        log_action(account_id=req.account_id,
                   action="Опубликовал объявления",
                   object_kind="объявления",
                   object_name="партия из %s шт." % len(_pub),
                   after_val="\n".join(_lines),
                   reason="публикация подтверждённых черновиков после успешной "
                          "проверки валидатором Avito; автоматический откат невозможен",
                   actor=ACTOR_USER, source="avito.publish_drafts")
    except Exception:
        pass

    # Сохраняем связку item_id -> A/B-вариант отдельно от фида (в XML/params это
    # попадать не должно - там только официальные теги Avito-шаблона). Нужно,
    # чтобы через несколько дней можно было сравнить конверсию authored vs ai_generated.
    try:
        from app.models.storage import Storage as _StorageModelAB
        import json as _json_ab
        import datetime as _dt_ab

        ab_row = db.query(_StorageModelAB).filter(
            _StorageModelAB.account_id == req.account_id, _StorageModelAB.key == "ab_test_links"
        ).first()
        ab_links = _json_ab.loads(ab_row.value) if ab_row else {}

        for d in to_publish:
            if d.get("variant") and d.get("batch_id"):
                ab_links[d.get("id")] = {
                    "variant": d.get("variant"),
                    "batch_id": d.get("batch_id"),
                    "batch_label": d.get("batch_label", ""),
                    "published_at": _dt_ab.datetime.utcnow().isoformat()
                }

        if ab_links:
            if ab_row:
                ab_row.value = _json_ab.dumps(ab_links, ensure_ascii=False)
            else:
                ab_row = _StorageModelAB(account_id=req.account_id, key="ab_test_links", value=_json_ab.dumps(ab_links, ensure_ascii=False))
                db.add(ab_row)
            db.commit()
    except Exception:
        pass  # A/B-связка необязательна для успешной публикации, не должна её ломать

    _push_notification(req.account_id, f"✅ Фид опубликован: {len(to_publish)} объявлений, 0 ошибок.")
    # Диагностика контракта в успешном ответе. Существующие поля и значение
    # status не меняются - фронт может быть на них завязан.
    _contract_status = "contract_required" if _new_without else "success"
    return {
        "status": "ok",
        "published": len(to_publish),
        "contract_status": _contract_status,
        "checked": len(_new_with),
        "blocked": [],
        "blocked_count": 0,
        "without_contract": [
            str(getattr(it, "id", "") or ("batch_index:%d" % idx))
            for idx, it in enumerate(_new_without)
        ],
        "contract_message": (
            "Часть объявлений опубликована без проверки параметров категории. "
            "Определите категорию Avito для полной проверки."
            if _new_without else ""
        ),
    }


def _client_money(account_id: str, db) -> dict:
    """Сколько клиент заплатил всего и когда последний раз."""
    import json as _json
    from app.models.storage import Storage
    try:
        row = db.query(Storage).filter(Storage.account_id == account_id,
                                       Storage.key == "payments_history").first()
        hist = _json.loads(row.value) if row else []
    except Exception:
        hist = []
    total = sum(h.get("amount_rub", 0) for h in hist)
    last = hist[-1] if hist else None
    return {"total_rub": total, "payments_count": len(hist),
            "last_at": (last or {}).get("at"), "last_title": (last or {}).get("title")}


def apply_banner_to_batch_impl(account_id: str, batch_label: str, banner_count: int = 5, photos_per_ad: int = 10, folder: str = "", on_progress=None, idempotency_key: str = "") -> dict:
    """Генерирует N рекламных баннеров под партию черновиков (batch_label) и расставляет фото
    у каждого черновика партии: баннер первым, дальше обычные фото по кругу из указанной папки.
    Общая реализация - используется и прямым эндпоинтом /apply_banner_to_batch, и GPT-экшеном
    apply_banner_to_batch в plan_items.py, чтобы не дублировать логику в двух местах."""
    import random as _rnd_banner_batch
    from app.api.banners import create_avito_safe_banner, get_banner_showcase

    banner_count = max(int(banner_count), 1)
    photos_per_ad = max(int(photos_per_ad), 1)

    all_drafts = _load_drafts(account_id)
    target = [d for d in all_drafts if d.get("batch_label") == batch_label]
    other = [d for d in all_drafts if d.get("batch_label") != batch_label]

    if not target:
        return {"status": "error", "message": f"Партия '{batch_label}' не найдена среди черновиков"}

    raw_description = (target[0].get("title", "") + ". " + target[0].get("description", ""))[:400]

    showcase_urls = []
    try:
        sc = get_banner_showcase(account_id)
        showcase_urls = [it.get("url") for it in sc.get("showcase", []) if it.get("url")]
    except Exception:
        pass

    accent_palette = ["#F79009", "#2F6FED", "#7C5CFC", "#F04438", "#12B76A", "#EE46BC", "#0EA5E9", "#EAB308"]

    # Stable economic intent for each banner in the batch. Every child artifact
    # has its own durable tariff intent too. This closes the crash window between
    # provider success and a later aggregate quota charge: an already-created file
    # is not linked into drafts until its exact child tariff consume is confirmed.
    _batch_idem = str(idempotency_key or "").strip()
    if not _batch_idem:
        return {"status":"idempotency_required","code":"paid_idempotency_required",
                "message":"Для платной генерации баннеров нужен ключ безопасного повтора."}
    _requested_banner_count = banner_count
    from app.api.banners import avito_safe_banner_replay_available
    from app.api.billing import check_and_consume as _bill_consume_b
    _directions = ("architecture", "result", "interior")
    _replay_indices = set()
    for _idx in range(_requested_banner_count):
        _child_key = _batch_idem + ":banner:" + str(_idx)
        if avito_safe_banner_replay_available(account_id, _child_key, _directions[_idx % 3]):
            _replay_indices.add(_idx)

    # Tariff preflight limits only NEW provider-capable child intents. Existing
    # artifacts are still revisited because an earlier worker may have crashed
    # after image persistence but before the child tariff ledger commit.
    banner_notice = None
    _new_candidates = [i for i in range(_requested_banner_count) if i not in _replay_indices]
    _allowed_new = len(_new_candidates)
    try:
        from app.api.billing import get_status as _bill_status_b
        stb = _bill_status_b(account_id)
        if not stb.get("unlimited"):
            rem_banners = max(0, int(stb["usage"].get("banners", {}).get("remaining", 0) or 0))
            _allowed_new = min(_allowed_new, rem_banners)
            if _allowed_new < len(_new_candidates):
                banner_notice = (
                    f"Лимит баннеров: готовых безопасных повторов {len(_replay_indices)}; "
                    f"новых можно создать {_allowed_new} из {len(_new_candidates)}."
                )
    except Exception as e:
        print(f"[billing] banners preflight failed closed: {e}", flush=True)
        _allowed_new = 0
        banner_notice = "BORIS временно не смог подтвердить тарифный лимит. Новые баннеры не создаются; уже сохранённые безопасно сверяются с тарифным журналом."

    _selected_new = set(_new_candidates[:_allowed_new])
    _selected_indices = sorted(_replay_indices | _selected_new)
    banner_urls = []
    newly_generated = 0
    replayed = 0
    _billing_pending = []
    for _progress_idx, bi in enumerate(_selected_indices):
        try:
            color = accent_palette[bi % len(accent_palette)]
            _artifact_key = _batch_idem + ":banner:" + str(bi)
            b_data = create_avito_safe_banner(
                account_id=account_id,
                description=raw_description,
                direction=_directions[bi % 3],
                accent_color=color,
                idempotency_key=_artifact_key,
            )
            if b_data.get("status") == "ok" and b_data.get("url"):
                # BILLING_CHILD_INTENT_EXACTLY_ONCE_V1: charge one child immediately
                # after the durable artifact exists and before it can affect drafts.
                # A crash/retry replays both the artifact and this tariff intent.
                _charge_key = _batch_idem + ":billing:banner:" + str(bi)
                try:
                    _charge = _bill_consume_b(account_id, "banners", 1, idempotency_key=_charge_key)
                except Exception as _bill_exc:
                    _billing_pending.append({"index":bi,"reason":str(_bill_exc)[:160]})
                    continue
                if not _charge.get("allowed", False):
                    _billing_pending.append({"index":bi,"reason":str(_charge.get("blocked_reason") or _charge.get("message") or "billing_pending")[:160]})
                    continue
                banner_urls.append(b_data.get("url"))
                if b_data.get("idempotency_replay"):
                    replayed += 1
                else:
                    newly_generated += 1
        except Exception as exc:
            print(f"[banner-batch] child {bi} failed: {str(exc)[:180]}", flush=True)
        if on_progress:
            try:
                on_progress(_progress_idx + 1, len(_selected_indices))
            except Exception:
                pass

    if _billing_pending:
        # Do not partially mutate a draft batch. Successfully settled child intents
        # are durable and free on retry; unresolved children will be settled before
        # linking on the next call, without another provider purchase.
        return {"status":"billing_pending","code":"billing_pending",
                "message":"Баннеры сохранены, но тарифный учёт части вариантов ещё не подтверждён. BORIS не изменил черновики; повтор безопасно продолжит с тех же файлов.",
                "notice":banner_notice,"pending":_billing_pending,
                "banners_generated":len(banner_urls),"banners_new":newly_generated,
                "banners_replayed":replayed,"batch_label":batch_label}

    if not banner_urls:
        if _new_candidates and _allowed_new == 0 and banner_notice:
            return {"status":"billing_pending","code":"billing_pending","message":banner_notice,"notice":banner_notice,
                    "banners_generated":0,"banners_new":0,"banners_replayed":0,"batch_label":batch_label}
        return {"status": "error", "message": f"Не удалось подготовить ни одного оплаченного баннера для партии '{batch_label}'", "notice": banner_notice}

    photo_urls = []
    if folder:
        photo_urls = images_list(account_id).get("folders", {}).get(folder, [])

    updated = []
    for di, d in enumerate(target):
        banner_url = banner_urls[di % len(banner_urls)]
        regular_needed = max(photos_per_ad - 1, 0)
        if photo_urls:
            pool = list(photo_urls)
            _rnd_banner_batch.shuffle(pool)
            regulars = [pool[j % len(pool)] for j in range(regular_needed)]
        else:
            regulars = d.get("images", [])[:regular_needed]
        d = dict(d)
        d["images"] = [banner_url] + regulars
        updated.append(d)

    # DRAFT_BATCH_BANNER_ATOMIC_MERGE_V1: banner generation can take minutes.
    # Reapply only the target draft ids against the latest locked snapshot so a
    # concurrent draft append/edit outside this batch is preserved.
    _updated_by_id = {str(d.get("id") or ""): d for d in updated if str(d.get("id") or "").strip()}
    def _merge_banner_batch(rows):
        out = []
        for row in rows:
            rid = str(row.get("id") or "")
            out.append(dict(_updated_by_id.get(rid, row)))
        return out
    _mutate_drafts(account_id, _merge_banner_batch)
    try:
        from app.services.action_log import log_action, ACTOR_USER
        log_action(account_id=account_id, action="Сделал баннеры для объявлений",
                   object_kind="объявления",
                   object_name="партия «%s», %s черновиков" % (batch_label, len(updated)),
                   after_val="создано баннеров: %s" % len(banner_urls),
                   reason=(banner_notice or "баннер поставлен первым фото у каждого "
                                            "объявления партии"),
                   actor=ACTOR_USER, source="avito.apply_banner_to_batch")
    except Exception:
        pass
    return {"status": "ok", "updated": len(updated), "banners_generated": len(banner_urls),
            "banners_new": newly_generated, "banners_replayed": replayed,
            "batch_label": batch_label, "notice": banner_notice}


